def validate_content():
    """Check the content contract and accessible HTML before generation."""
    import re
    from html.parser import HTMLParser
    from urllib.parse import urlsplit

    class FragmentCheck(HTMLParser):
        allowed = {"section", "h2", "h3", "p", "strong", "em", "table", "caption",
                   "thead", "tbody", "tr", "th", "td", "ul", "ol", "li", "figure",
                   "figcaption", "details", "summary", "blockquote", "a", "br", "div", "span"}

        def __init__(self):
            super().__init__()
            self.stack = []
            self.counts = {}

        def handle_starttag(self, tag, attrs):
            assert tag in self.allowed, f"Unexpected or malformed HTML tag: {self.get_starttag_text()}"
            values = dict(attrs)
            assert not any(key.startswith("on") for key in values), "Inline scripts are not permitted"
            if tag == "th":
                assert values.get("scope") in {"row", "col"}, "Table headers need an explicit scope"
            self.counts[tag] = self.counts.get(tag, 0) + 1
            if tag != "br":
                self.stack.append(tag)

        def handle_endtag(self, tag):
            assert self.stack and self.stack[-1] == tag, f"Invalid HTML nesting at </{tag}>"
            self.stack.pop()

        def check(self, fragment):
            assert not re.search(r"</?h\s+[1-6]\b", fragment), "Malformed heading such as <h 2>"
            self.feed(fragment)
            self.close()
            assert not self.stack, "Unclosed HTML elements"
            for parent, child in (("table", "caption"), ("figure", "figcaption"), ("details", "summary")):
                assert self.counts.get(parent, 0) == self.counts.get(child, 0), f"Missing {child}"

    assert [unit["number"] for unit in UNITS] == list(range(1, 13))
    assert len({unit["slug"] for unit in UNITS}) == 12
    for unit in UNITS:
        for key in ("learn_html", "try_html", "build_html"):
            FragmentCheck().check(unit[key])
        check = unit["finish_check"]
        assert len(check["choices"]) == 3 and 0 <= check["answer"] < 3
        assert check["question"] and check["explanation"]
        assert len(unit["readings"]) == 1, "Keep one focused reading per unit"
        for reading in unit["readings"]:
            assert all(reading[key] for key in ("title", "url", "purpose"))
            assert urlsplit(reading["url"]).scheme == "https" and not re.search(r"\s", reading["url"])
    assert [milestone["number"] for milestone in MILESTONES] == list(range(1, 6))
    assert sum(milestone["weight"] for milestone in MILESTONES) == 100
    for milestone in MILESTONES:
        FragmentCheck().check(milestone["brief_html"])
        assert sum(criterion["weight"] for criterion in milestone["rubric"]) == 100
        assert UNITS[milestone["unit"] - 1]["milestone"] == milestone["number"]
    assert sum(item["weight"] for item in MILESTONES[-1]["rubric"] if item["criterion"].startswith("Individual")) == 40
    FragmentCheck().check(COURSE_CASE_HTML)
    # A deliberate regression probe ensures the validator rejects the prior typo.
    try:
        FragmentCheck().check("<h 2>Broken heading</h 2>")
    except AssertionError:
        pass
    else:
        raise AssertionError("Malformed-heading regression check did not detect the typo")
    return True


if __name__ == "__main__":
    validate_content()
    print("Validated 12 units, 5 milestones, and 42 accessible HTML fragments.")
